local AnvilMaker = {}
local PRODUCTS = {
    iron_anvil = { name = "Železno nakovalo", ironCost = 6, woodCost = 1, leatherCost = 1, time = 7, cost = 230, prestige = 5, happiness = 2, description = "Železno nakovalo za osnovno kovaštvo." },
    bronze_anvil = { name = "Bronasto nakovalo", bronzeCost = 6, ironCost = 1, woodCost = 1, leatherCost = 1, time = 9, cost = 555, prestige = 7, happiness = 3, description = "Bronasto nakovalo za stabilno kovaštvo." },
    silver_anvil = { name = "Srebrno nakovalo", silverCost = 6, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 13, cost = 1330, prestige = 12, happiness = 4, description = "Srebrno nakovalo za plemiške kovače." },
    gilded_anvil = { name = "Pozlačeno nakovalo", goldCost = 1, silverCost = 6, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 17, cost = 2870, prestige = 21, happiness = 5, description = "Pozlačeno nakovalo za dvorne kovače." },
    jewel_set_anvil = { name = "Draguljasto nakovalo", goldCost = 2, silverCost = 6, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 21, cost = 6150, prestige = 37, happiness = 7, description = "Draguljasto nakovalo za kraljevske kovače." },
    royal_sovereign_anvil = { name = "Kraljevski suvereno nakovalo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 28, cost = 13100, prestige = 71, happiness = 13, description = "Suvereno nakovalo z biseri za krono." },
}
local BUILDINGS = {
    anvil_workshop = { name = "Nakovalna delavnica", cost = { gold = 395, wood = 175, stone = 160, iron = 12 }, upkeep = 8, qualityBonus = 5 },
    anvil_house = { name = "Nakovalna hiša", cost = { gold = 1340, wood = 360, stone = 300, silver = 8, iron = 10 }, upkeep = 29, qualityBonus = 18 },
    master_anvil_atelier = { name = "Mojstrski nakovalni atelje", cost = { gold = 3280, wood = 425, stone = 555, silver = 40, gold = 8 }, upkeep = 77, qualityBonus = 30 },
    sovereign_anvil_palace = { name = "Suverena nakovalna palača", cost = { gold = 13900, wood = 655, stone = 875, gold = 90, jewel = 20 }, upkeep = 266, qualityBonus = 55, prestigeBonus = 50 },
}
AnvilMaker.ironStock = 22; AnvilMaker.bronzeStock = 16; AnvilMaker.woodStock = 8; AnvilMaker.leatherStock = 8; AnvilMaker.silverStock = 8; AnvilMaker.goldStock = 6; AnvilMaker.jewelStock = 4; AnvilMaker.pearlStock = 4
AnvilMaker.productStock = {}; AnvilMaker.buildings = {}; AnvilMaker.maker = nil; AnvilMaker.activeMaking = {}; AnvilMaker.totalProducts = 0; AnvilMaker.dayTimer = 0
function AnvilMaker.init() AnvilMaker.ironStock=22; AnvilMaker.bronzeStock=16; AnvilMaker.woodStock=8; AnvilMaker.leatherStock=8; AnvilMaker.silverStock=8; AnvilMaker.goldStock=6; AnvilMaker.jewelStock=4; AnvilMaker.pearlStock=4; AnvilMaker.productStock={}; AnvilMaker.buildings={}; AnvilMaker.maker=nil; AnvilMaker.activeMaking={}; AnvilMaker.totalProducts=0; AnvilMaker.dayTimer=0; print("[AnvilMaker] Royal Anvil Maker System initialized (6 products, 4 buildings)") end
function AnvilMaker.hireMaker(n,s) s=s or math.random(55,90); local c=595+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AnvilMaker.maker={name=n or ("Nakovalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nakovalar najet: %s (spretnost: %d)",AnvilMaker.maker.name,s),"success") end; return true end
function AnvilMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AnvilMaker.build(id) local ok,e=AnvilMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AnvilMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AnvilMaker.getQualityBonus() local b=0; for _,bd in ipairs(AnvilMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AnvilMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and AnvilMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and AnvilMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and AnvilMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and AnvilMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and AnvilMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AnvilMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AnvilMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AnvilMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AnvilMaker.buildings==0 then return false,"Potrebna nakovalna delavnica" end; if not AnvilMaker.maker then return false,"Potreben nakovalar" end; return true end
function AnvilMaker.make(pt,qty) qty=qty or 1; local ok,e=AnvilMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then AnvilMaker.ironStock=AnvilMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then AnvilMaker.bronzeStock=AnvilMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then AnvilMaker.woodStock=AnvilMaker.woodStock-d.woodCost*qty end; if d.leatherCost then AnvilMaker.leatherStock=AnvilMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then AnvilMaker.silverStock=AnvilMaker.silverStock-d.silverCost*qty end; if d.goldCost then AnvilMaker.goldStock=AnvilMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AnvilMaker.jewelStock=AnvilMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AnvilMaker.pearlStock=AnvilMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AnvilMaker.maker then t=math.max(1,t-math.floor(AnvilMaker.maker.skill/13)) end; table.insert(AnvilMaker.activeMaking,{id="anvil_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AnvilMaker.completeMaking(m) local q=1.0+(AnvilMaker.getQualityBonus()/100); if AnvilMaker.maker then q=q+(AnvilMaker.maker.skill/140) end; q=math.min(2.5,q); AnvilMaker.productStock[m.productType]=(AnvilMaker.productStock[m.productType] or 0)+m.quantity; AnvilMaker.totalProducts=AnvilMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AnvilMaker.maker then AnvilMaker.maker.itemsMade=AnvilMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AnvilMaker.maker.skill=math.min(100,AnvilMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nakovalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"anvil.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function AnvilMaker.update(dt) if not _G.state then return end; AnvilMaker.dayTimer=AnvilMaker.dayTimer+dt; if AnvilMaker.dayTimer>=30 then AnvilMaker.dayTimer=0; for i=#AnvilMaker.activeMaking,1,-1 do local m=AnvilMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AnvilMaker.completeMaking(m); table.remove(AnvilMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AnvilMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AnvilMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AnvilMaker.getStats() return {ironStock=AnvilMaker.ironStock,bronzeStock=AnvilMaker.bronzeStock,woodStock=AnvilMaker.woodStock,leatherStock=AnvilMaker.leatherStock,silverStock=AnvilMaker.silverStock,goldStock=AnvilMaker.goldStock,jewelStock=AnvilMaker.jewelStock,pearlStock=AnvilMaker.pearlStock,productStock=AnvilMaker.productStock,numBuildings=#AnvilMaker.buildings,hasMaker=AnvilMaker.maker~=nil,makerName=AnvilMaker.maker and AnvilMaker.maker.name or "—",makerSkill=AnvilMaker.maker and AnvilMaker.maker.skill or 0,activeMaking=#AnvilMaker.activeMaking,totalProducts=AnvilMaker.totalProducts} end
return AnvilMaker
